SELECT CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END signup_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(subscriptions.plan))) plan_values, MIN(subscriptions.end_date) first_end_date FROM subscriptions LEFT JOIN customers ON subscriptions.customer_id = customers.id GROUP BY CASE WHEN YEAR(customers.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(customers.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END
